sys_script.script:
/**
 * Route Grievance to Department
 *
 * Before-insert routing: maps grievance_category to the owning departmental
 * group and populates assignment_group ONLY when it is empty, so an explicit
 * choice made by a citizen-facing form, an agent, or an integration is never
 * overwritten.
 *
 * Runs at order 150, ahead of "Generate Ticket Hash" (order 200).
 * assignment_group is not part of the hash payload
 * (citizen_name|citizen_phone|description), so routing cannot affect the
 * integrity digest.
 */
(function executeRule(current, previous /*null when async*/) {
    var CATEGORY_TO_GROUP = {
        water: 'Water Supply Dept',
        electricity: 'Electricity Board Dept',
        sanitation: 'Sanitation & Waste Dept',
        roads: 'Roads & Infrastructure Dept',
    }

    // Respect an assignment group that is already set.
    if (current.getValue('assignment_group')) {
        return
    }

    var category = (current.getValue('grievance_category') || '').trim().toLowerCase()

    if (!category) {
        return
    }

    var groupName = CATEGORY_TO_GROUP[category]

    if (!groupName) {
        gs.warn(
            '[Grievance Routing] No department mapped for category "' +
                category +
                '". Leaving assignment_group empty for manual triage.',
        )
        return
    }

    // Resolved by name rather than a hardcoded sys_id so the rule stays valid
    // across instances where the groups were installed with different sys_ids.
    var grp = new GlideRecord('sys_user_group')
    grp.addQuery('name', groupName)
    grp.addQuery('active', true)
    grp.setLimit(1)
    grp.query()

    if (grp.next()) {
        current.setValue('assignment_group', grp.getUniqueValue())
    } else {
        gs.warn(
            '[Grievance Routing] Department group "' +
                groupName +
                '" was not found or is inactive. Leaving assignment_group empty for manual triage.',
        )
    }
})(current, previous)
